// devices.device.register — generated by `pnpm gen:command devices register-device`. Fill in the input, the change and the
// audit record. SOP rules go in ../rules (pnpm gen:rule), table access in ../repository.ts (02-architecture §3).
import { z } from 'zod';
import { defineCommand } from '../../kernel/index.ts';
import { devicesPermissions } from '../permissions.ts';

export const registerDevice = defineCommand({
  name: 'devices.device.register',
  permission: devicesPermissions.registerDevice,
  input: z.object({ id: z.uuid() }),
  describe: (i) =>
    `Register a device on a project: SN, MAC, model, firmware, network, status (E4 AC1) ${i.id}`,
  handle: (_ctx, i) =>
    Promise.resolve({
      result: { id: i.id },
      audit: { objectType: 'device', objectId: i.id, clientId: null, before: null, after: null },
    }),
});
